-- ===========================================================================
-- RITHI CRM — Search performance (trigram indexes): apply bundle
--
-- pg_trgm trigram indexes so substring searches (product, party, call
-- registers) are index-backed instead of full table scans — the fix for
-- "canceling statement due to statement timeout" on Search. Runs last so
-- every table it indexes already exists; skips the calls view / absent columns.
--
-- GENERATED by scripts/build-apply-bundles.mjs — do not edit by hand.
-- Edit the migrations below and re-run the generator.
--
-- Carries, in order:
--   0052_search_indexes.sql
--   0098_product_register_names.sql
--   0099_no_jit.sql
--   0101_kpi_views.sql
--   0128_kpi_field_inst.sql
--   0131_kpi_phase2.sql
--   0142_consumption_report.sql
--   0147_unused_spare_report.sql
--   0148_spare_insights.sql
--   0149_part_master_fields.sql
--   0152_part_category_free_text.sql
--   0159_kpi_export_lateral.sql
--
-- Paste into the Supabase SQL Editor and Run. Safe to run more than once.
-- ===========================================================================

-- Stop with a readable list rather than a cryptic error partway through.
do $$
declare missing text[] := '{}';
begin

  if array_length(missing, 1) is not null then
    raise exception E'Apply these first, then re-run this bundle:\n  - %',
      array_to_string(missing, E'\n  - ');
  end if;
end $$;


begin;

-- ------------------------------------------------------------------------
-- 0052_search_indexes.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Search performance. The app searches with substring ILIKE ('%term%') across
-- products, parties and the call registers. A leading wildcard cannot use the
-- existing lower(col) btree indexes, so every search seq-scans the whole table
-- and, once the tables grew, hit the API statement timeout ("canceling
-- statement due to statement timeout") on every page.
--
-- pg_trgm trigram GIN indexes make substring/ILIKE matching index-backed. This
-- block installs pg_trgm and adds a trigram index for each searched column that
-- exists, on each base table that exists — so it works before or after the call
-- split (0040): the `calls` VIEW is skipped, its base tables are indexed.
-- Idempotent (create index if not exists); safe to re-run.
-- ===========================================================================

create extension if not exists pg_trgm;

do $$
declare
  trgm text;   -- schema pg_trgm actually lives in (extensions on Supabase)
  rec  record;
  idx  text;
begin
  select quote_ident(n.nspname) into trgm
    from pg_extension e join pg_namespace n on n.oid = e.extnamespace
   where e.extname = 'pg_trgm';
  if trgm is null then raise notice 'pg_trgm not available — skipping'; return; end if;

  for rec in
    select tbl, col from (values
      ('products','serial_number'), ('products','item_name'), ('products','party_name'),
      ('parties','party_name'),
      ('field_calls','ucn'), ('field_calls','call_number'), ('field_calls','party_name'),
      ('field_calls','serial'), ('field_calls','product_name'), ('field_calls','allocated_to'),
      ('field_calls','city'), ('field_calls','state'), ('field_calls','standard_complaint'),
      ('field_calls','complaint_reported'), ('field_calls','customer_name'),
      ('installation_calls','ucn'), ('installation_calls','call_number'), ('installation_calls','party_name'),
      ('installation_calls','serial'), ('installation_calls','product_name'), ('installation_calls','allocated_to'),
      ('installation_calls','city'), ('installation_calls','state'), ('installation_calls','standard_complaint'),
      ('installation_calls','complaint_reported'), ('installation_calls','customer_name'),
      ('pm_calls','ucn'), ('pm_calls','call_number'), ('pm_calls','party_name'),
      ('pm_calls','serial'), ('pm_calls','product_name'), ('pm_calls','allocated_to'),
      ('pm_calls','city'), ('pm_calls','state'), ('pm_calls','standard_complaint'),
      ('pm_calls','complaint_reported'), ('pm_calls','customer_name'),
      ('calls','ucn'), ('calls','call_number'), ('calls','party_name'),
      ('calls','serial'), ('calls','product_name'), ('calls','allocated_to'),
      ('calls','city'), ('calls','state'), ('calls','standard_complaint'),
      ('calls','complaint_reported'), ('calls','customer_name')
    ) as v(tbl, col)
  loop
    -- table must exist and be an ordinary table (skip the calls VIEW after split)
    if to_regclass('public.' || rec.tbl) is null then continue; end if;
    if (select relkind from pg_class where oid = ('public.' || rec.tbl)::regclass) <> 'r' then continue; end if;
    -- column must exist on it
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = rec.tbl and column_name = rec.col) then
      continue;
    end if;
    idx := rec.tbl || '_' || rec.col || '_trgm';
    execute format('create index if not exists %I on public.%I using gin (%I %s.gin_trgm_ops)',
                   idx, rec.tbl, rec.col, trgm);
  end loop;
end $$;

-- Btree indexes for the EXACT-match / IN lookups (a trigram index does not
-- serve `=`/`IN`): the request cascade filters products by party_name (and
-- item_name) with eq, and openCallsFor looks up calls by serial / party_name
-- with IN. Without these, those lookups seq-scan and time out too.
do $$
declare rec record; idx text;
begin
  for rec in
    select tbl, col from (values
      ('products','party_name'), ('products','item_name'),
      ('field_calls','serial'), ('field_calls','party_name'),
      ('installation_calls','serial'), ('installation_calls','party_name'),
      ('pm_calls','serial'), ('pm_calls','party_name'),
      ('calls','serial'), ('calls','party_name')
    ) as v(tbl, col)
  loop
    if to_regclass('public.' || rec.tbl) is null then continue; end if;
    if (select relkind from pg_class where oid = ('public.' || rec.tbl)::regclass) <> 'r' then continue; end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = rec.tbl and column_name = rec.col) then
      continue;
    end if;
    idx := rec.tbl || '_' || rec.col || '_eq';
    execute format('create index if not exists %I on public.%I (%I)', idx, rec.tbl, rec.col);
  end loop;
end $$;

-- Refresh planner stats so the new indexes are used right away.
do $$
declare t text;
begin
  foreach t in array array['products','parties','field_calls','installation_calls','pm_calls','calls'] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute 'analyze public.' || quote_ident(t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0098_product_register_names.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE PRODUCT LIST COMES FROM THE PRODUCT REGISTER.
--
-- Product & Party Search was filling its product dropdown from the `product`
-- master value list. That is a list somebody maintains, and it can be empty,
-- short, or spelled differently from the register — which is what the screen
-- showed. The register itself is the authority on what products exist: a
-- machine is in it or it is not.
--
-- PostgREST cannot ask for `select distinct`, so the distinct list is a view.
-- It carries the count as well, because "MONNAL T75 (1,204)" tells the person
-- choosing far more than the name alone, and it costs nothing to group once.
--
-- The serial dropdown that depends on it needs no view: it is
-- `item_name = <the one chosen>`, which 0052's btree on products(item_name)
-- already serves. (A trigram index does NOT serve equality — that lesson cost
-- this project a fortnight of timeouts.)
-- ===========================================================================

create or replace view public.product_register_names as
  select item_name,
         count(*)::int as machines
    from public.products
   where coalesce(item_name, '') <> ''
   group by item_name;

-- `create or replace view` does NOT carry `security_invoker` forward, so it is
-- asserted every time the view is written. Without it the view would read the
-- register as its owner and hand back rows RLS meant to withhold.
alter view public.product_register_names set (security_invoker = on);

grant select on public.product_register_names to authenticated;

-- ------------------------------------------------------------------------
-- 0099_no_jit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE HAND STOCK TIMEOUT WAS JIT COMPILATION, NOT THE QUERY.
--
-- Hand Stock timed out, then took 11-14 seconds, then 3-5 after 0095. Every
-- reading pointed at row-level security, because switching RLS off made it
-- instant. It was the right symptom and the wrong cause. `EXPLAIN ANALYZE`
-- with the JIT block showing says it plainly:
--
--     Timing: Generation 23 ms, Inlining 145 ms,
--             Optimization 2134 ms, Emission 1440 ms, Total 3742 ms
--     Execution Time: 3912 ms
--
-- Three and three-quarter seconds COMPILING a query that then runs in under
-- two hundred milliseconds. The trigger is `jit_above_cost` (100,000): the
-- planner's ESTIMATE for the nine-arm movement view is half a million, almost
-- all of it invented by the cost of RLS sub-plans it will barely run. So the
-- more access rules a query carries, the more certain Postgres is to spend
-- seconds compiling it — and that is why turning RLS off "fixed" it.
--
-- With JIT off, and NOTHING else changed, the whole 102,893-row history reads
-- in 323 ms. Closed through 2025 it is 174 ms. Measured on a copy of the live
-- data, as the `authenticated` role, with every policy in force.
--
-- Nothing in this application benefits from JIT. These are sub-second API
-- queries; compiling them can only ever cost more than it saves. Off is the
-- right setting for the whole database, not a special case for one screen.
--
-- TO PUT IT BACK: `alter database postgres reset jit;`
--
-- It applies to CONNECTIONS MADE AFTER IT RUNS. Pooled connections already
-- open keep the old setting, so give it a few minutes — or restart the project
-- — before judging whether it worked.
-- ===========================================================================

do $$
begin
  execute format('alter database %I set jit = off', current_database());
  raise notice 'JIT disabled for database % — new connections only.', current_database();
exception
  when insufficient_privilege then
    raise notice 'Could not disable JIT: this role does not own the database. Set it in the Supabase dashboard, or run: alter database postgres set jit = off;';
end $$;

-- ------------------------------------------------------------------------
-- 0101_kpi_views.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- KPIs THAT COME FROM THE RECORD, NOT FROM A SPREADSHEET.
--
-- Three questions the service function actually asks, each answered by an
-- aggregate the database computes rather than a page that pulls forty thousand
-- rows across the wire and adds them up in a browser:
--
--   FAILURE RATE      how often does a product fail, per machine in the field?
--                     A count of calls means nothing on its own — a product with
--                     1,200 machines SHOULD generate more calls than one with 40.
--                     The denominator is the install base, which the Product
--                     Register already holds.
--
--   SPARE USE BY COVER  what do we spend on parts under warranty, under CMC,
--                     under AMC, and out of guarantee? The cover is on the CALL,
--                     the parts are on the consumption; the join is the answer.
--
--   SPARE USE BY REGION  the same figure per region, so a region consuming twice
--                     its share can be looked at rather than guessed at.
--
-- EVERY VIEW IS security_invoker, so an engineer's KPIs are their own calls and
-- a manager's are their team's. The numbers a person sees are the numbers they
-- are allowed to see, without a second set of rules to keep in step.
--
-- `create or replace view` does NOT carry security_invoker over — it is asserted
-- on every one of them, every time.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One row per part consumed, carrying what the call says about it. This is the
-- grain everything else rolls up from; it is also worth reading on its own when
-- a number looks wrong.
--
-- The cover (`item_status`) and the region are FACTS ABOUT THE CALL AND THE
-- ENGINEER, not about the part, so they are read from there rather than copied
-- onto the consumption row where they would age.
-- ---------------------------------------------------------------------------
create or replace view public.spare_usage as
  select c.id,
         c.ucn,
         c.call_number,
         c.part,
         public.part_code(c.part)                            as part_code,
         coalesce(c.qty, 0)                                  as qty,
         coalesce(nullif(btrim(c.engineer), ''), '')         as engineer,
         coalesce(nullif(btrim(k.item_status), ''), 'Not stated') as cover,
         coalesce(nullif(btrim(k.product_name), ''), '')     as product,
         coalesce(nullif(btrim(k.call_type), ''), '')        as call_type,
         coalesce(nullif(btrim(k.city), ''), '')             as city,
         coalesce(nullif(btrim(ud.region), ''), 'No region') as region,
         coalesce(nullif(btrim(c.source), ''), 'Engineer')   as source,
         c.created_at                                        as consumed_at
    from public.spare_consumption c
    left join public.calls k on k.ucn = c.ucn
    left join public.user_directory ud
           on lower(btrim(ud.name)) = lower(btrim(coalesce(nullif(c.engineer, ''), k.allocated_to)))
   where coalesce(c.qty, 0) <> 0;
alter view public.spare_usage set (security_invoker = on);
grant select on public.spare_usage to authenticated;

-- ---------------------------------------------------------------------------
-- Spare use by cover, region and product, in one rollup the screen pivots.
--
-- One row per combination rather than three separate views: a few thousand rows
-- at most, and a client that has them can answer "CMC in the South" without
-- another round trip — and, more to the point, without the three views being
-- able to disagree with each other.
-- ---------------------------------------------------------------------------
create or replace view public.spare_usage_rollup as
  select cover, region, product,
         count(*)::int                     as lines,
         sum(qty)                          as qty,
         count(distinct ucn)::int          as calls,
         count(distinct part_code)::int    as parts,
         count(distinct engineer)::int     as engineers
    from public.spare_usage
   group by cover, region, product;
alter view public.spare_usage_rollup set (security_invoker = on);
grant select on public.spare_usage_rollup to authenticated;

-- ---------------------------------------------------------------------------
-- FAILURE RATE — calls per hundred machines in the field, over twelve months.
--
-- `machines` is the install base from the Product Register and is NOT scoped by
-- who is asking: it is a property of the fleet, the same number for everybody.
-- `calls_12m` is scoped, because it is a count of calls. So an engineer reads
-- their own share of a fleet-wide denominator, which is the honest reading of
-- what they can see, and a rate is only comparable between products for someone
-- who can see all the calls. The screen says so.
--
-- Twelve months because a reliability figure needs a period; the same view
-- carries the all-time count beside it so a young product is not read as a
-- reliable one.
-- ---------------------------------------------------------------------------
create or replace view public.failure_rate_by_product as
  with fleet as (
    select coalesce(nullif(btrim(item_name), ''), '') as product, count(*)::int as machines
      from public.products
     where coalesce(btrim(item_name), '') <> ''
     group by 1
  ), calls as (
    select coalesce(nullif(btrim(product_name), ''), '') as product,
           count(*)::int as calls_total,
           count(*) filter (where reg_date >= (current_date - 365))::int as calls_12m,
           count(*) filter (where open_state <> 'Solved')::int as calls_open
      from public.calls
     where coalesce(btrim(product_name), '') <> ''
     group by 1
  )
  select coalesce(f.product, c.product)      as product,
         coalesce(f.machines, 0)             as machines,
         coalesce(c.calls_total, 0)          as calls_total,
         coalesce(c.calls_12m, 0)            as calls_12m,
         coalesce(c.calls_open, 0)           as calls_open,
         case when coalesce(f.machines, 0) > 0
              then round(coalesce(c.calls_12m, 0)::numeric * 100 / f.machines, 1)
         end                                  as per_100_machines
    from fleet f
    full join calls c on c.product = f.product;
alter view public.failure_rate_by_product set (security_invoker = on);
grant select on public.failure_rate_by_product to authenticated;

-- ---------------------------------------------------------------------------
-- HOW a product fails, not just how often. The standard complaint is the field
-- the service desk already chooses from a controlled list, so it is the one
-- thing in the record that groups reliably across thousands of calls.
-- ---------------------------------------------------------------------------
create or replace view public.failure_modes_by_product as
  select coalesce(nullif(btrim(product_name), ''), '')       as product,
         coalesce(nullif(btrim(standard_complaint), ''), 'Not stated') as complaint,
         count(*)::int                                       as calls,
         count(*) filter (where reg_date >= (current_date - 365))::int as calls_12m
    from public.calls
   where coalesce(btrim(product_name), '') <> ''
   group by 1, 2;
alter view public.failure_modes_by_product set (security_invoker = on);
grant select on public.failure_modes_by_product to authenticated;

-- The joins these views make, indexed. `spare_consumption.ucn` is the one that
-- matters: without it every rollup is a hash of the whole consumption history
-- against the whole call register.
create index if not exists spare_consumption_ucn_idx on public.spare_consumption (ucn);
create index if not exists field_calls_product_idx on public.field_calls (product_name);
create index if not exists installation_calls_product_idx on public.installation_calls (product_name);
create index if not exists pm_calls_product_idx on public.pm_calls (product_name);

-- ------------------------------------------------------------------------
-- 0128_kpi_field_inst.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE KPI WORKBOOK'S "Field_INST" SHEET, FROM THE REGISTER.
--
-- The user's KPI workbook is maintained by hand; this is its Field_INST tab
-- computed from the calls instead. PHASE 1 (their scoping, 2026-09-07) is
-- columns A to AB — the same fields, in the same order, under the same
-- headings — plus the two dates the sheet fills in by eye. AC to AG (Attended
-- in Days, Solved in Days, TTA, TTS, Failure Month) are formulas in the
-- workbook and are Phase 2.
--
-- THE THREE RULES THEY GAVE, and each is a decision, not a detail:
--
--   CALL ATTENDED ON = the EARLIER of the first visit and the first spare
--   request. A spare raised before anyone visits is still somebody attending
--   to the call — often the first thing that happens on a fault that needs a
--   part. `least()` ignores NULLs in Postgres, so a call with one and not the
--   other gets the one it has, and a call with neither is blank.
--
--   CALL SOLVED = the visit date of the entry that moved it to "Solved -
--   Report Completed". Not the last visit, and not the day somebody typed it
--   in: the visit on which the machine was actually fixed. Where a call was
--   solved, reopened and solved again, it is the LATEST such entry, because
--   that is the one the call's current status comes from (0032 — the latest
--   ENTRY, `updated_at desc, id desc`, not the latest visit DATE).
--
--   OPEN / CLOSE = Close ONLY when the call is Solved - Report Completed.
--   Anything else is Open, including "Solved - Report Pending": the workbook
--   counted a report-pending call as open and so does this.
--
--   CANCELLED CALLS ARE NOT CONSIDERED AT ALL — not as Open, not as Close,
--   not in the row count. The sheet counted them as Close, which is why its
--   581 "Close" rows are 563 completed calls plus 18 cancellations; this view
--   drops them, so Close means solved and nothing else.
--
-- PM calls are not here: the workbook keeps them on their own tab.
-- ===========================================================================

-- DROPPED AND RECREATED, not `create or replace`. 0131 adds six columns to
-- this view, and `create or replace view` CANNOT DROP COLUMNS — so replaying
-- this file on a database that already has Phase 2 failed with "cannot drop
-- columns from view" and took the whole performance bundle down with it. Found
-- by `npm run check:replay`, which is what it is for. Nothing depends on this
-- view, so the drop is free.
drop view if exists public.kpi_field_inst;
create view public.kpi_field_inst as
with c as (
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.field_calls where cancelled_at is null
  union all
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.installation_calls where cancelled_at is null
),
-- The call's CURRENT visit — the latest ENTRY, which is what its status comes
-- from. A call with no visit has none, and reads as Unattended below.
latest as (
  select distinct on (ucn) ucn, call_status, pending_reason, engineer
    from public.reports
   order by ucn, updated_at desc, id desc
),
-- The entry that put it at Solved - Report Completed, latest first so a call
-- solved twice reports the solve that is currently standing.
solved as (
  select distinct on (ucn) ucn, visit_at
    from public.reports
   where call_status ilike 'solved%report%complet%'
   order by ucn, updated_at desc, id desc
),
first_visit as (
  select ucn, min(visit_at) as at from public.reports where visit_at is not null group by ucn
),
-- The first spare RAISED on the call. or_req_date is the request's own date;
-- created_at is when the row was written, and is the fallback for an imported
-- request that never carried one.
first_spare as (
  select ucn, min(coalesce(or_req_date, created_at::date)) as on_date
    from public.spare_requests
   where coalesce(btrim(ucn), '') <> ''
   group by ucn
)
select
  c.ucn                                          as "UC Number",
  c.call_number                                  as "Call Number",
  coalesce(c.reg_at, c.reg_date::timestamptz)    as "Call Registeration Date",
  c.complaint_date                               as "Complaint Date",
  c.party_name                                   as "Party Name",
  c.city                                         as "City",
  c.state                                        as "State",
  c.product_name                                 as "Product Name",
  c.serial                                       as "Product Serial Number",
  c.item_status                                  as "Item Status",
  c.warranty_number                              as "Warranty Number",
  c.warranty_start                               as "Warranty Start Date",
  c.warranty_end                                 as "Warranty End Date",
  c.contract_number                              as "Contract Number",
  c.contract_start                               as "Contract Start Date",
  c.contract_end                                 as "Contract End Date",
  c.contract_type                                as "Contract Type",
  c.call_type                                    as "Call Type",
  c.standard_complaint                           as "Standard Complaint",
  c.complaint_reported                           as "Complaint Reported",
  c.allocated_to                                 as "Call Allocated To",
  c.breakdown_date                               as "Breakdown Date",
  case when s.visit_at is not null then 'Close' else 'Open' end
                                                 as "Open/Close",
  coalesce(nullif(btrim(l.call_status), ''), 'Unattended')
                                                 as "Call Status",
  coalesce(l.pending_reason, '')                 as "CALL PENDING REASON",
  coalesce(l.engineer, '')                       as "Visiting Service Engineer",
  least(fv.at::date, fs.on_date)                 as "Call Attended On",
  s.visit_at::date                               as "Call Solved Date & Time"
  from c
  left join latest      l  on l.ucn  = c.ucn
  left join solved      s  on s.ucn  = c.ucn
  left join first_visit fv on fv.ucn = c.ucn
  left join first_spare fs on fs.ucn = c.ucn;

-- READS AS THE READER. Without this the view runs as its owner and row-level
-- security stops applying: an engineer's export would be every call in the
-- company. `create or replace view` DROPS the setting, so it is re-asserted
-- here and must be on every rebuild (CLAUDE.md).
alter view public.kpi_field_inst set (security_invoker = on);
grant select on public.kpi_field_inst to authenticated;

comment on view public.kpi_field_inst is
  'The KPI workbook''s Field_INST tab, columns A-AB, from the register. Cancelled calls are excluded entirely; Close means Solved - Report Completed and nothing else; Call Attended On is the earlier of the first visit and the first spare request; Call Solved is the visit date of the entry that completed it. AC-AG are workbook formulas (Phase 2).';

-- ------------------------------------------------------------------------
-- 0131_kpi_phase2.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PHASE 2 — the five computed columns, and the one the workbook does not have.
--
-- The formulas are the workbook's own, read out of the file rather than
-- guessed, and confirmed against its own cached answers:
--
--   AC Attended in Days = IF(MIN(attended-complaint, attended-registered) < 0,
--                            0, that MIN)
--   AD Solved in Days   = the same, from the solved date
--   AE TTA (R)          = VLOOKUP(AC, band table)
--   AF TTS (R)          = VLOOKUP(AD, band table)
--   AG Failure Month    = TEXT(registration date, "YYYY MMM")
--
-- MIN of the two differences means the count runs from the LATER of the
-- complaint and the registration. A call complained about on the 30th and
-- registered on the 3rd of the next month, attended on the 30th, is 0 days —
-- not -4 and not 12.
--
-- THE FOUR DECISIONS (user, 2026-09-07), each of which the sheet answers
-- differently or not at all:
--
--  1. AN UNATTENDED CALL GETS PENDING DAYS, IN A COLUMN OF ITS OWN. The sheet
--     computes AC and AD for a call nobody has been to and gets 0 — Excel reads
--     a blank date as zero — so every unattended call in the file reads
--     "attended and solved the same day, 00-03D", and is counted in the bands.
--     Here those two stay NULL and `Pending Days` says how long it has actually
--     been waiting. Computed for every OPEN call, not only Unattended: a call
--     left Unsolved for 200 days is the same question being asked.
--
--  2. THE FINER BANDS. LOOKUPVALUES holds two tables; Field_INST used the
--     coarse one for both, so a machine open eleven months read the same as one
--     open sixty-one days. Both TTA and TTS now use the finer bands, which are
--     the same up to 60 days and then keep going: 61-90D, 91-180D, >180D,
--     >1 yr, >2 yrs, >3 yrs, >4 yrs, >5 yrs.
--
--  3. SOLVED - REPORT PENDING IS **CLOSE**, per the sheet's own lookup. This
--     REVERSES 0128, where it was Open on the user's earlier instruction. The
--     solved DATE is unchanged — it is still the visit that reached Solved -
--     Report Completed — so a report-pending call is Close with no solved date
--     and therefore no Solved in Days. That is what the workbook shows too.
--
--  4. FAILURE MONTH IS OFF THE REGISTRATION DATE, not the complaint date, as
--     the formula has it.
--
-- Cancelled calls are still excluded from the view entirely (0128): that is
-- about which rows exist at all, not about Open and Close.
-- ===========================================================================

-- The band table, as a function so it is written once and both columns use it.
-- The bounds are LOOKUPVALUES!H:L, which is the finer of the two.
create or replace function public.kpi_days_band(p_days integer)
returns text language sql immutable as $$
  select case
    when p_days is null then null
    when p_days <    0 then '00-03D'      -- the sheet's -300..-1 row; floored anyway
    when p_days <=   3 then '00-03D'
    when p_days <=   7 then '04-07D'
    when p_days <=  30 then '08-30D'
    when p_days <=  60 then '31-60D'
    when p_days <=  90 then '61-90D'
    when p_days <= 180 then '91-180D'
    when p_days <= 365 then '>180D'
    when p_days <= 730 then '>1 yr'
    when p_days <= 1080 then '>2 yrs'
    when p_days <= 1460 then '>3 yrs'
    when p_days <= 1825 then '>4 yrs'
    else '>5 yrs'
  end;
$$;
comment on function public.kpi_days_band(integer) is
  'The KPI workbook''s TTA / TTS band for a day count, using LOOKUPVALUES''s FINER table (H:L) — the same as the coarse one to 60 days, then 61-90D, 91-180D, >180D, >1 yr … >5 yrs.';

-- Dropped first for the same reason 0128 is: whichever of the two runs last
-- must not be constrained by the shape the other left behind.
drop view if exists public.kpi_field_inst;
create view public.kpi_field_inst as
with c as (
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.field_calls where cancelled_at is null
  union all
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.installation_calls where cancelled_at is null
),
latest as (
  select distinct on (ucn) ucn, call_status, pending_reason, engineer
    from public.reports order by ucn, updated_at desc, id desc
),
solved as (
  select distinct on (ucn) ucn, visit_at
    from public.reports
   where call_status ilike 'solved%report%complet%'
   order by ucn, updated_at desc, id desc
),
first_visit as (
  select ucn, min(visit_at) as at from public.reports where visit_at is not null group by ucn
),
first_spare as (
  select ucn, min(coalesce(or_req_date, created_at::date)) as on_date
    from public.spare_requests
   where coalesce(btrim(ucn), '') <> ''
   group by ucn
),
r as (
  select
    c.*,
    l.call_status, l.pending_reason, l.engineer,
    s.visit_at::date                              as solved_on,
    least(fv.at::date, fs.on_date)                as attended_on,
    -- The count runs from the LATER of complaint and registration: MIN of the
    -- two differences is the same thing said the workbook's way.
    greatest(c.complaint_date, coalesce(c.reg_at::date, c.reg_date))
                                                  as counts_from,
    coalesce(nullif(btrim(l.call_status), ''), 'Unattended') as status_now
    from c
    left join latest      l  on l.ucn  = c.ucn
    left join solved      s  on s.ucn  = c.ucn
    left join first_visit fv on fv.ucn = c.ucn
    left join first_spare fs on fs.ucn = c.ucn
)
select
  r.ucn                                          as "UC Number",
  r.call_number                                  as "Call Number",
  coalesce(r.reg_at, r.reg_date::timestamptz)    as "Call Registeration Date",
  r.complaint_date                               as "Complaint Date",
  r.party_name                                   as "Party Name",
  r.city                                         as "City",
  r.state                                        as "State",
  r.product_name                                 as "Product Name",
  r.serial                                       as "Product Serial Number",
  r.item_status                                  as "Item Status",
  r.warranty_number                              as "Warranty Number",
  r.warranty_start                               as "Warranty Start Date",
  r.warranty_end                                 as "Warranty End Date",
  r.contract_number                              as "Contract Number",
  r.contract_start                               as "Contract Start Date",
  r.contract_end                                 as "Contract End Date",
  r.contract_type                                as "Contract Type",
  r.call_type                                    as "Call Type",
  r.standard_complaint                           as "Standard Complaint",
  r.complaint_reported                           as "Complaint Reported",
  r.allocated_to                                 as "Call Allocated To",
  r.breakdown_date                               as "Breakdown Date",
  -- DECISION 3: any Solved... status is Close, report-pending included.
  case when r.status_now ilike 'solved%' then 'Close' else 'Open' end
                                                 as "Open/Close",
  r.status_now                                   as "Call Status",
  coalesce(r.pending_reason, '')                 as "CALL PENDING REASON",
  coalesce(r.engineer, '')                       as "Visiting Service Engineer",
  r.attended_on                                  as "Call Attended On",
  r.solved_on                                    as "Call Solved Date & Time",
  -- AC / AD. NULL when the thing being measured has not happened, rather than
  -- the sheet's 0 — see decision 1.
  --
  -- THE GUARD IS NOT DECORATION. `greatest()` IGNORES NULLs in Postgres, so
  -- `greatest(null - date, 0)` is 0, not null — and an unattended call would
  -- read "attended in 0 days, 00-03D", which is precisely the sheet behaviour
  -- this decision exists to undo. Caught by test 10, which was written for it.
  -- (It is the same property `least()` has, and there it is what we want: see
  -- Call Attended On in 0128.)
  case when r.attended_on is null or r.counts_from is null then null
       else greatest((r.attended_on - r.counts_from)::int, 0) end as "Attended in Days",
  case when r.solved_on is null or r.counts_from is null then null
       else greatest((r.solved_on - r.counts_from)::int, 0) end   as "Solved in Days",
  public.kpi_days_band(
    case when r.attended_on is null or r.counts_from is null then null
         else greatest((r.attended_on - r.counts_from)::int, 0) end)      as "TTA ( R )",
  public.kpi_days_band(
    case when r.solved_on is null or r.counts_from is null then null
         else greatest((r.solved_on - r.counts_from)::int, 0) end)        as "TTS ( R )",
  to_char(coalesce(r.reg_at, r.reg_date::timestamptz), 'YYYY Mon')        as "Failure Month",
  -- The column the workbook does not have. How long an OPEN call has been
  -- waiting, today — the question the sheet answered with a 0 that read as
  -- "attended and solved the same day".
  case when r.status_now ilike 'solved%' or r.counts_from is null then null
       else greatest(((now() at time zone 'Asia/Kolkata')::date - r.counts_from)::int, 0)
  end                                            as "Pending Days"
  from r;

alter view public.kpi_field_inst set (security_invoker = on);
grant select on public.kpi_field_inst to authenticated;

comment on view public.kpi_field_inst is
  'The KPI workbook''s Field_INST tab from the register: A-AB as the sheet has them, AC-AG computed by its own formulas, plus Pending Days for a call still open. Cancelled calls excluded entirely. Close is any Solved... status, report-pending included. A day count is NULL where the event has not happened, never 0.';

-- ------------------------------------------------------------------------
-- 0142_consumption_report.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE CONSUMPTION REPORT — one row per spare booked, with its call around it.
--
-- The user, 2026-09-08, with a screenshot of the sheet they keep by hand: "i
-- need the attached format for consumption report. add all the additional
-- column present in the consumption table to the end. add a provision for the
-- user to add filter before downloading and also the user should be able to
-- select the required column -- whatever is in screenshot has to be there
-- ( Mandatory Columns) rest the user can add or remove."
--
-- So the view is in TWO HALVES, and the order is the point:
--
--   the first sixteen  the screenshot's own columns, in its own order. The page
--                      will not let these be turned off -- they are what makes
--                      the file the report somebody already recognises.
--   everything after   every remaining column of `spare_consumption`, appended.
--                      Off by default, there to be switched on.
--
-- A LINE IS NOT A VISIT. `spare_consumption` is keyed on the UCN and the call
-- number; it carries no reference to the visit that used the part. The two date
-- columns the screenshot asks for therefore come from the call's LATEST visit
-- (`updated_at` is when the register was told, `visit_at` when the engineer was
-- actually there -- the same two dates the reliability export carries, and they
-- disagree often enough to be worth both). Where a call has no visit yet, both
-- are blank rather than guessed.
--
-- `part` IS "CODE|Description" -- one string, the same one the Part Master and a
-- hand-stock line use. The screenshot splits it across two columns ("Spares
-- Used" holds MP-010, "Part name" holds OXYGEN SENSOR-Envitec-...), so the view
-- splits it once, here, rather than in every consumer.
--
-- THE ENGINEER: the consumption line's own, falling back to the visit's. The
-- line is written by whoever booked the part, which is the visiting engineer in
-- every ordinary case; the fallback covers a line reconciled later by the Spare
-- Coordinator, where the visit still knows who was there.
--
-- SECURITY INVOKER, so a reader sees only the calls their role allows -- the
-- rule this project has been bitten by three times (0040, 0050, 0057). A report
-- is exactly the kind of screen where a leak would go unnoticed.
-- ===========================================================================

drop view if exists public.consumption_report;

create view public.consumption_report as
with last_visit as (
  -- The LATEST entry, not the latest visit date: a call's state comes from the
  -- last thing somebody wrote, which is `sync_call_last_visit()`'s ordering in
  -- 0032 and has to stay the same here.
  select distinct on (ucn) ucn, visit_at, updated_at, engineer
    from public.reports
   order by ucn, updated_at desc, id desc
)
select
  -- ---- the sixteen the screenshot asks for, in its order --------------------
  sc.ucn                                             as "UC Number",
  sc.call_number                                     as "Call Number",
  c.call_type                                        as "Call Type",
  v.updated_at                                       as "Visit Entry Date",
  v.visit_at                                         as "Visit Date & Time",
  coalesce(nullif(btrim(sc.engineer), ''), v.engineer, '')
                                                     as "Visiting Service Engineer",
  -- `part` is "CODE|Description"; split once here so no consumer has to.
  btrim(split_part(sc.part, '|', 1))                 as "Spares Used",
  btrim(substr(sc.part, strpos(sc.part, '|') + 1))   as "Part name",
  sc.qty                                             as "QTY",
  c.product_name                                     as "Product",
  c.serial                                           as "Serial No",
  c.party_name                                       as "Customer",
  c.city                                             as "City",
  c.standard_complaint                               as "Complaint",
  c.item_status                                      as "Item Status",
  c.reg_date                                         as "Call Date",
  -- ---- then every other column of spare_consumption -------------------------
  sc.id                                              as "Line ID",
  sc.part                                            as "Part (code|description)",
  sc.source                                          as "Source",
  sc.remarks                                         as "Remarks",
  sc.recorded_by                                     as "Recorded By",
  sc.engineer_email                                  as "Engineer Email",
  sc.original_qty                                    as "Original Qty",
  sc.adjusted_by                                     as "Adjusted By",
  sc.adjusted_at                                     as "Adjusted At",
  sc.adjustment_reason                               as "Adjustment Reason",
  sc.grir                                            as "GRIR",
  sc.source_ref                                      as "Source Ref",
  sc.source_ref_key                                  as "Source Ref Key",
  sc.created_at                                      as "Created At",
  sc.created_by                                      as "Created By",
  sc.data                                            as "Extra (import)",
  -- ---- and the call's, for filtering and for anyone who wants them ----------
  c.complaint_reported                               as "Nature of Complaint",
  c.state                                            as "State",
  c.allocated_to                                     as "Allocated To",
  c.open_state                                       as "Call Status",
  c.warranty_number                                  as "Warranty No",
  c.contract_number                                  as "Contract No",
  c.contract_type                                    as "Contract Type"
  from public.spare_consumption sc
  left join public.calls c    on c.ucn = sc.ucn
  left join last_visit v      on v.ucn = sc.ucn;

alter view public.consumption_report set (security_invoker = on);

grant select on public.consumption_report to authenticated;

comment on view public.consumption_report is
  'One row per spare booked, with its call and that call''s latest visit around it. The first sixteen columns are the user''s own report format, in their order; everything after is the rest of spare_consumption plus the call fields worth filtering on. `part` is split into code and description here so no consumer repeats it. security_invoker, so a reader sees only the calls their role allows.';

-- ------------------------------------------------------------------------
-- 0147_unused_spare_report.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- NOT CONSUMED AGAINST THIS CALL — spares that reached the engineer and were
-- not fully booked against the call they were sent for.
--
-- THE REPORT IS CALLED "Not Consumed Against this Call" (the user renamed it,
-- 2026-09-08). The VIEW keeps the name `unused_spare_report`: it is referenced
-- by _status.sql row 112, the query helpers and the test suite, and renaming a
-- database object to follow a label is churn with a migration attached. The
-- name people read is the one on the screen.
--
-- The user, 2026-09-08: "Flag if something was Requested but never used in the
-- Consumption of that call. --- 'Not Used as per the Request' -- Create a
-- Separate Report of these Flagged items."
--
-- WHAT IT MEANS, precisely, because the wording admits three readings and only
-- one of them is a finding:
--
--   * A part that never got past an approver is NOT here. It was refused, so
--     there was nothing to use; that is a decision on the spare register, not a
--     discrepancy on the call.
--   * A part Stores DROPPED is not here either. Approved and then not sent is a
--     supply failure -- worth knowing, and visible on the call -- but again
--     nothing arrived, so nothing could be fitted.
--   * A part on an OPEN call is not here. Until the call is solved the part is
--     legitimately still in the van -- the engineer has not finished, and
--     consumption is booked when the work is done.
--   * A part that WAS DISPATCHED (or acknowledged as received), on a SOLVED
--     call, and is not fully accounted for in that call's consumption IS here. Two findings, not one
--     (the user, 2026-09-08: "Flag if there is a Qty Mismatch as well - Say 2
--     Nos are requested but only 1 Consumed"):
--
--       NOT USED   nothing of that part was booked on the call at all.
--       SHORT      some was booked, but less than was sent -- 2 sent, 1 used.
--
--     Either way the part is fitted and unrecorded, or still in the van. Both
--     are worth chasing and neither is visible anywhere today.
--
-- AGGREGATED PER CALL AND PART, NOT PER LINE, and that is a correctness point
-- rather than a tidiness one. A part can be sent twice on one call -- two
-- orders, or a partial issue followed by the rest -- and comparing each LINE
-- against the call's consumption would flag both lines as short whenever the
-- engineer booked the total in one entry. The question being asked is "was what
-- we sent for this call used on it?", which is a question about the part, so
-- the quantities are summed on both sides before they are compared.
--
-- DISPATCHED COUNTS AS REACHED, and this is the user's own rule (2026-09-08):
-- "Dispatch is considered as reached, it is not considered as In Transit since
-- it is not Mandatory to mark a Spare as Received."
--
-- It is written down here because the opposite looks more careful and is
-- wrong. Requiring `received_at` would be the obvious tightening for somebody
-- reading this later -- and it would empty the report, because acknowledging a
-- delivery is optional and most lines never get one. The report would then say
-- "nothing to chase" for the same reason it should have said "chase all of
-- these", which is the worst failure available to it. Do not narrow this to
-- Received without making the acknowledgement mandatory first.
--
-- MATCHED ON THE PART CODE, NOT THE WHOLE STRING. Both sides store
-- "CODE|Description" and the description drifts -- case, spacing, a part
-- renamed in the master after the request was raised. Matching the whole thing
-- would report a part as unused because somebody re-typed its name, which is
-- the worst kind of false finding: confident, specific and wrong.
--
-- SCOPED TO THE CALL. A part consumed on a DIFFERENT call does not clear this
-- one: the question is whether what was sent FOR THIS CALL was used ON IT.
--
-- A VIEW, not a computation in the browser. The registers page, so a check done
-- on the loaded rows would report on the first page and call it the whole
-- answer -- the same reason the consumption report's filters run in the
-- database (0142).
--
-- SECURITY INVOKER, so a reader sees only the calls their role allows. It joins
-- `calls`, which is itself invoker (0105), and a view that reads as its owner
-- over RLS-protected tables is the exact shape `npm run check:views` rejects.
-- ===========================================================================

drop view if exists public.unused_spare_report;
create view public.unused_spare_report as
with sent as (
  -- Every line that actually reached the engineer. The stage tests mirror
  -- deriveStage() in src/lib/spareflow.ts: a rejection at any approval stage
  -- wins over everything, then a drop, and what is left as dispatched-or-
  -- received is what arrived.
  select
    r.ucn,
    upper(btrim(split_part(l.part, '|', 1)))                        as part_code,
    btrim(coalesce(nullif(split_part(l.part, '|', 2), ''), l.part)) as part_name,
    -- `dispatched_qty` DEFAULTS TO 0, not null, so a plain coalesce reports
    -- every line as "0 sent" -- which the test caught on its first run.
    coalesce(nullif(l.dispatched_qty, 0), l.qty)                    as qty_sent,
    coalesce(nullif(btrim(r.or_no), ''), r.uid)                     as or_no,
    r.uid                                                            as request_uid,
    r.engineer, r.engineer_email, r.party_name, r.product_name, r.serial,
    r.item_status, r.call_number,
    l.dc_number, l.dispatched_at, l.received_at
  from public.spare_request_lines l
  join public.spare_requests r on r.uid = l.request_uid
  where btrim(coalesce(r.ucn, '')) <> ''
    -- Arrived.
    and (l.received_at is not null or coalesce(l.stores_status, '') ilike '%dispatch%')
    -- ...and was not refused or dropped on the way.
    and coalesce(l.stores_status, '') not ilike '%drop%'
    and coalesce(l.rm_approval, '')         !~* 'reject'
    and coalesce(l.commercial_approval, '') !~* 'reject'
    and coalesce(l.nsm_approval, '')        !~* 'reject'
),
sent_total as (
  -- One row per call and part: what was sent, in total, however many orders it
  -- took. The identifiers are joined rather than picked, because with two
  -- orders there genuinely are two of them and choosing one would hide the
  -- other from whoever has to chase it.
  select
    ucn,
    part_code,
    min(part_name)                                          as part_name,
    sum(qty_sent)                                           as qty_sent,
    string_agg(distinct or_no, ', ' order by or_no)          as or_no,
    string_agg(distinct nullif(btrim(dc_number), ''), ', ')  as dc_number,
    string_agg(distinct request_uid, ', ')                   as request_uid,
    string_agg(distinct nullif(btrim(engineer), ''), ', ')   as engineer,
    min(engineer_email)                                      as engineer_email,
    min(party_name)                                          as party_name,
    min(product_name)                                        as product_name,
    min(serial)                                              as serial,
    min(item_status)                                         as item_status,
    min(call_number)                                         as call_number,
    max(dispatched_at)                                       as dispatched_at,
    max(received_at)                                         as received_at,
    bool_or(received_at is not null)                         as any_received
  from sent
  group by ucn, part_code
),
booked as (
  -- What was consumed against each call, by part code. A VOIDED line has qty 0
  -- and is deliberately still counted as a booking of zero: the part was fitted
  -- and then the entry corrected, and 0049 keeps the row so that story
  -- survives. Where the void took the total below what was sent, that IS a
  -- shortfall and the report should say so.
  select c.ucn,
         upper(btrim(split_part(c.part, '|', 1))) as part_code,
         sum(coalesce(c.qty, 0))                  as qty_used
    from public.spare_consumption c
   group by 1, 2
)
select
  s.ucn,
  s.call_number,
  s.or_no                                    as "OR No",
  s.part_code                                as "Part Code",
  s.part_name                                as "Part name",
  s.qty_sent                                 as "Qty Sent",
  coalesce(b.qty_used, 0)                    as "Qty Used",
  s.qty_sent - coalesce(b.qty_used, 0)       as "Qty Short",
  -- WHICH FINDING IT IS, in the row, so the report can be read and sorted
  -- without doing the arithmetic. "Not used" and "short by one of two" call for
  -- different conversations.
  case when coalesce(b.qty_used, 0) = 0 then 'Not used' else 'Short' end as "Finding",
  case when s.any_received then 'Received' else 'Dispatched' end          as "Stage",
  s.dc_number                                as "DC No",
  s.dispatched_at::date                      as "Dispatched On",
  s.received_at::date                        as "Received On",
  s.engineer                                 as "Engineer",
  s.party_name                               as "Customer",
  s.product_name                             as "Product",
  s.serial                                   as "Serial No",
  s.item_status                              as "Item Status",
  c.reg_date                                 as "Call Registered",
  c.open_state                               as "Call Status",
  c.allocated_to                             as "Allotted To",
  c.state                                    as "State",
  c.city                                     as "City",
  s.request_uid                              as "Request UID",
  s.engineer_email                           as "Engineer Email"
  from sent_total s
  left join booked b on b.ucn = s.ucn and b.part_code = s.part_code
  left join public.calls c on c.ucn = s.ucn
 where coalesce(b.qty_used, 0) < s.qty_sent      -- none of it, or not all of it
   and s.part_code <> ''
   -- ONLY ONCE THE CALL IS SOLVED (the user, 2026-09-08: "Dont Flag till a Call
   -- is Solved. Flag only if the Call is solved."). While a call is open the
   -- part is legitimately still in the van: the engineer has not finished, and
   -- consumption is booked when the work is done. Flagging an open call reports
   -- the ordinary course of business as a discrepancy, and a report that cries
   -- wolf on live work is one people learn to close.
   --
   -- An INNER condition on a LEFT JOIN, deliberately: a consumption line whose
   -- call is not in `calls` at all has no state to be solved, and is not a
   -- finding either.
   and c.open_state = 'Solved';

alter view public.unused_spare_report set (security_invoker = on);
grant select on public.unused_spare_report to authenticated;

comment on view public.unused_spare_report is
  'Not Consumed Against this Call (the report''s name; this view keeps its own): two findings -- NOT USED (nothing of that part booked on the call) and SHORT (less booked than was sent). Aggregated per call and part, never per line: a part sent twice on one call would otherwise flag both lines as short whenever the engineer booked the total once. DISPATCHED counts as reached, because acknowledging a delivery is not mandatory and requiring it would empty the report. Spare lines dispatched or received against a call whose part code never appears in that call''s consumption. Refused and dropped lines are excluded -- nothing arrived, so nothing could be fitted. Matched on the part CODE because both sides store CODE|Description and the description drifts. security_invoker, so a reader sees only the calls their role allows.';

-- ------------------------------------------------------------------------
-- 0148_spare_insights.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SPARE INSIGHTS — what is being consumed, against what cover, on which
-- products, and whether it is a consumable or a spare.
--
-- The user, 2026-09-08: "Give me an Insight on the Spares Consumed - Default
-- the Consumption date to 1Jan2026 to Today - Selectable. Spares Consumed -
-- Highest Consumption ; Same against Product Item Status ; Then by Products
-- (Count of Spares Consumed) -- Also Categorize them as Consumable and Spare".
--
-- THE CATEGORY DID NOT EXIST, and this is the part worth saying out loud.
-- `parts` has code, description and item detail and nothing that says whether a
-- thing is a consumable or a spare; no master list defines it either. Three
-- ways to answer that:
--
--   1. GUESS FROM THE DESCRIPTION -- "filter", "kit", "sensor". It would have
--      filled the chart today and been wrong in a way nobody could see: a
--      figure derived from a keyword match reads exactly like one derived from
--      a decision, and this one lands next to consumption figures people act
--      on. Not done.
--   2. ASK, AND BUILD NOTHING until the answer arrives.
--   3. MAKE IT DATA, default it to UNCLASSIFIED, and show how much is
--      unclassified on the screen itself.
--
-- Three. `parts.category` is set on Part Master, one part at a time or in bulk,
-- and until somebody sets it a part is Unclassified and SAYS SO. A dashboard
-- that reports "60% consumables" out of a catalogue nobody has classified is
-- worse than one that reports "1,400 of 2,100 lines are unclassified" -- the
-- first is a number to act on, the second is a job to finish.
--
-- ONE FUNCTION, FIVE BREAKDOWNS, ONE ROUND TRIP. They share a filter and a
-- date window; five separate queries would be five chances for the screen to
-- show a total that does not match the rows under it.
--
-- SECURITY INVOKER (the default, and left that way deliberately): it reads
-- `spare_consumption` and `calls`, both behind RLS, so a reader sees the
-- consumption their role allows and no more. A definer here would quietly show
-- an engineer the whole company's figures.
-- ===========================================================================

-- ---- the category, as data -------------------------------------------------
alter table public.parts add column if not exists category text not null default '';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'parts_category_check') then
    -- FIVE VALUES, NOT TWO, because the Item Master's own column has four and
    -- 86% of its rows are blank. "Spare / Consumable" turned out to be
    -- SPARE (131), PRODUCT (45), CONSUMABLE (7), LABOUR (5) and empty (1,136)
    -- across 1,324 parts -- so a two-value vocabulary would have rejected the
    -- import, and a required one would have forced somebody to invent 1,136
    -- answers. Empty stays legal and reads as Unclassified.
    alter table public.parts add constraint parts_category_check
      check (category in ('', 'Consumable', 'Spare', 'Product', 'Labour'));
  end if;
end $$;

comment on column public.parts.category is
  'Consumable | Spare | Product | Labour | '''' (unclassified) -- the Item Master''s own vocabulary. Set on Part Master or loaded from that file. Empty means nobody has said yet, and Spare Insights reports it as Unclassified rather than folding it into either bucket.';

create index if not exists parts_category_idx on public.parts (category) where category <> '';

-- ---------------------------------------------------------------------------
-- THE INSIGHT. One call, one date window, five answers.
--
-- Consumption stores the part as "CODE|Description"; the part master stores the
-- code bare. So the join is on the CODE, upper-cased and trimmed -- the same
-- rule the Not Consumed report uses, and for the same reason: the description
-- drifts and the code does not.
--
-- DATED BY `created_at`, which is when the consumption was BOOKED. The visit it
-- belongs to has its own date, and the two disagree; booking is the event this
-- report is about ("consumption date"), and it is the one that cannot be
-- back-dated by hand.
-- ---------------------------------------------------------------------------
drop function if exists public.spare_insights(date, date);
create function public.spare_insights(p_from date, p_to date)
returns jsonb
language sql
stable
set search_path = public
as $$
with lines as (
  select
    upper(btrim(split_part(sc.part, '|', 1)))                          as part_code,
    btrim(coalesce(nullif(split_part(sc.part, '|', 2), ''), sc.part))  as part_name,
    coalesce(sc.qty, 0)                                                as qty,
    sc.ucn,
    sc.engineer,
    c.product_name,
    c.item_status,
    c.party_name
  from public.spare_consumption sc
  left join public.calls c on c.ucn = sc.ucn
  where sc.created_at >= p_from::timestamptz
    and sc.created_at <  (p_to + 1)::timestamptz     -- inclusive of p_to
    and coalesce(sc.qty, 0) > 0                      -- a voided line is not consumption
),
priced as (
  select l.*,
         coalesce(nullif(btrim(p.category), ''), 'Unclassified') as category
    from lines l
    left join public.parts p
      on upper(btrim(p.code)) = l.part_code
),
by_part as (
  select part_code, min(part_name) as part_name, sum(qty) as qty,
         count(distinct ucn) as calls, min(category) as category
    from priced group by part_code order by sum(qty) desc, part_code limit 25
),
by_cover as (
  select coalesce(nullif(btrim(item_status), ''), '— not set —') as cover,
         sum(qty) as qty, count(distinct ucn) as calls, count(*) as lines
    from priced group by 1 order by sum(qty) desc
),
by_product as (
  select coalesce(nullif(btrim(product_name), ''), '— not set —') as product,
         sum(qty) as qty, count(*) as lines, count(distinct ucn) as calls,
         count(distinct part_code) as parts
    from priced group by 1 order by sum(qty) desc, 1 limit 25
),
by_category as (
  select category, sum(qty) as qty, count(*) as lines, count(distinct part_code) as parts
    from priced group by 1 order by sum(qty) desc
),
by_month as (
  -- The shape of the window, so a spike has somewhere to show.
  select to_char(date_trunc('month', sc.created_at), 'YYYY-MM') as month,
         sum(coalesce(sc.qty, 0)) as qty
    from public.spare_consumption sc
   where sc.created_at >= p_from::timestamptz
     and sc.created_at <  (p_to + 1)::timestamptz
     and coalesce(sc.qty, 0) > 0
   group by 1 order by 1
)
select jsonb_build_object(
  'from', p_from,
  'to',   p_to,
  'total', (select jsonb_build_object(
              'qty',   coalesce(sum(qty), 0),
              'lines', count(*),
              'parts', count(distinct part_code),
              'calls', count(distinct ucn),
              -- WHAT THE CATEGORY SPLIT IS BUILT ON. Shown on the screen, so a
              -- consumable/spare figure is read next to how much of the
              -- catalogue has actually been classified.
              'unclassified_lines', count(*) filter (where category = 'Unclassified'),
              'unclassified_qty',   coalesce(sum(qty) filter (where category = 'Unclassified'), 0)
            ) from priced),
  'by_part',     (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from by_part b),
  'by_cover',    (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from by_cover b),
  'by_product',  (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from by_product b),
  'by_category', (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from by_category b),
  'by_month',    (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from by_month b)
);
$$;

grant execute on function public.spare_insights(date, date) to authenticated;

comment on function public.spare_insights(date, date) is
  'Spare consumption over a date window, five ways: the biggest consumers, the cover (item status) they were fitted under, the products they went into, the consumable/spare split, and the shape by month. SECURITY INVOKER, so a reader sees only the consumption their role allows. Dated by when the consumption was BOOKED (created_at). Voided lines (qty 0) are excluded: a corrected entry is not consumption.';

-- ------------------------------------------------------------------------
-- 0149_part_master_fields.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE PART MASTER CARRIES WHAT THE ITEM MASTER HAS.
--
-- The user, 2026-09-08, on the Consumable/Spare split: "Ideally should be
-- Present in the Part Master, if its not then Use the Above File and also make
-- Provision to Record all the Fields in the Part Master."
--
-- The file loads TODAY -- the Part Master importer already reads `Item Code`,
-- `Item Details`, `Item Name`, `Active/Inactive?` and `Added On`, and drops
-- everything else into `extra` as free-form jsonb. That is why this migration
-- exists: a value in `extra` is KEPT but cannot be grouped, filtered or shown
-- as a column, so "Spare / Consumable" was in the database and still unusable.
-- Promoting them is the difference between storing a file and having its data.
--
-- WHAT COMES ACROSS, and why each is a column rather than a note:
--
--   product          the machine family (EXT, ORG, CPX, MT75…). 443 of 1,324
--                    rows have none, so it is nullable and stays that way.
--   purchase_cost    what the part costs. Consumption times cost is the next
--                    question anybody asks of the insight, and it cannot be
--                    asked of a jsonb blob.
--   purchase_cost_f  the same in foreign currency, as the file keeps it.
--   source_*         the old system's OWN audit stamps (added on/by, modified
--                    on, set to inactive on). Named `source_` so they can never
--                    be mistaken for this system's `created_at`: they say what
--                    AppSheet recorded, not what happened here.
--
-- `category` is in 0148 with the insight that reads it.
-- ===========================================================================

alter table public.parts
  add column if not exists product            text,
  add column if not exists purchase_cost      numeric,
  add column if not exists purchase_cost_f    numeric,
  add column if not exists source_added_by    text,
  add column if not exists source_added_on    timestamptz,
  add column if not exists source_modified_on timestamptz,
  add column if not exists source_inactive_on timestamptz;

-- The family is a filter on Part Master and a grouping in the insight; 443 of
-- 1,324 rows have none, so the index skips them rather than indexing a third
-- of the table as empty string.
create index if not exists parts_product_idx on public.parts (product) where product is not null and product <> '';

comment on column public.parts.product is
  'The machine family this part belongs to (EXT, ORG, CPX, MT75...), from the Item Master. Blank on about a third of the catalogue.';
comment on column public.parts.purchase_cost is
  'Purchase cost from the Item Master. Present on 560 of 1,324 rows, so any figure derived from it must say what it covers.';
comment on column public.parts.source_added_on is
  'When the SUPERSEDED system recorded this part. Not this system''s created_at, which is when the row arrived here.';

-- ------------------------------------------------------------------------
-- 0152_part_category_free_text.sql
-- ------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- THE PART CATEGORY IS SOURCE DATA, NOT A CONTROLLED VOCABULARY.
--
-- Reported 2026-09-09, loading the Item Master through Bulk Uploads:
--
--   new row for relation "parts" violates check constraint
--   "parts_category_check" (row ~174) (173 written before it stopped.)
--
-- 0148 added that check with the four words the Item Master uses. The words
-- were right; the PLACE was wrong. Two things went wrong together and only one
-- of them was the importer's:
--
--   1. The importer's normaliser ran only where the file left the cell EMPTY,
--      so it never saw the values it existed to title-case, and every non-blank
--      row went in as the file's own SPARE / PRODUCT / CONSUMABLE / LABOUR.
--      Fixed in `uploads.ts` (`always: true`) and needs no SQL.
--
--   2. A CHECK on this column can ABORT AN IMPORT PART-WRITTEN. That is what
--      this migration is about, and it would still be true with the importer
--      fixed: the day the Item Master gains a fifth word, or somebody types one
--      on Part Master, a 1,300-row load stops in the middle again and leaves
--      the table half-updated. A vocabulary worth having is worth reporting on;
--      it is not worth refusing data over.
--
-- SO THE CONSTRAINT GOES AND NOTHING REPLACES IT. Spare Insights already deals
-- with a word it does not know -- it groups by whatever the column says and
-- reports blank as Unclassified -- so an unexpected category now appears in the
-- chart as its own bar, which is how somebody notices it and decides what it
-- ought to be. That is a better outcome than the value never arriving.
--
-- The column keeps `not null default ''`: blank still means "nobody has said",
-- which is a different statement from any word and must stay distinguishable.
--
-- Idempotent, and safe to run before or after a re-import.
-- ---------------------------------------------------------------------------

alter table public.parts drop constraint if exists parts_category_check;

comment on column public.parts.category is
  'The Item Master''s own Spare / Consumable word -- Spare, Consumable, Product, Labour, or anything else that file carries -- title-cased on import. '''' means nobody has said yet, and Spare Insights reports that as Unclassified rather than folding it into a bucket. Deliberately NOT constrained (0152): a check here aborts a bulk import part-written, and a category is worth reporting on rather than refusing data over.';

-- ------------------------------------------------------------------------
-- 0159_kpi_export_lateral.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- KPI EXPORT — the same answer, without reading the whole register to give it.
--
-- REPORTED 2026-09-10: "Sivarani is unable to download KPI Report" —
-- "Could not export: canceling statement due to statement timeout" on a range
-- holding 455 calls.
--
-- MEASURED, not guessed. Against a database seeded to the live shape (24,000
-- calls, 55,000 visits, 12,000 spare requests), one month of the export:
--
--     as superuser (RLS BYPASSED) ..........    160 ms
--     as a Hotline engineer (RLS applied) ... 27,273 ms
--
-- The 170x is the whole story, and it is why this looked fine to every check
-- that has ever been run against this view: everything here runs as the owner
-- unless somebody signs in.
--
-- WHY. The view pre-aggregated the WHOLE of `reports` and `spare_requests` in
-- four CTEs, then joined the result to the calls. Those CTEs do not depend on
-- which calls were asked for, so the caller's date range CANNOT be pushed into
-- them: exporting 455 calls scanned all 55,000 visits, three times over.
--
-- Under RLS that is not merely 55,000 rows. `reports_read` carries
-- `exists (select 1 from calls c where c.ucn = reports.ucn ...)`, and `calls` is
-- itself a VIEW over three call tables that each carry their own policy. So the
-- entire call-visibility stack was re-evaluated per report row — the plan came
-- back with more than a hundred nested SubPlans.
--
-- THE FIX IS TO CORRELATE, not to index around it. The four aggregates become
-- LATERAL lookups keyed on the call in hand, so the date range narrows the calls
-- FIRST and only those calls touch `reports` at all. The policy then runs over
-- the rows being exported instead of the register.
--
-- The semantics are unchanged, deliberately and line by line:
--   * `latest` was `distinct on (ucn) ... order by ucn, updated_at desc, id desc`
--     — the latest ENTRY, not the latest visit (0032). `order by updated_at
--     desc, id desc limit 1` on one ucn is the same row.
--   * `solved` is that, filtered to the status that completed the call.
--   * `first_visit` is min(visit_at) ignoring rows with no visit date.
--   * `first_spare` is min(coalesce(or_req_date, created_at::date)), and keeps
--     the guard that an EMPTY ucn matches nothing — without it a call with a
--     blank ucn would pick up every ucn-less spare request in the table.
--
-- REPLACED, NOT DROPPED. `create or replace` keeps the column list identical
-- (which is all it allows) and avoids the AccessExclusiveLock that made 0154
-- deadlock against the live app. And `security_invoker` is re-asserted below,
-- because create-or-replace DROPS it — the fault that has exposed every call to
-- every user three times in this project (0040, 0050, 0057).
-- ===========================================================================

-- `first_spare` looks up spare requests by ucn, and there was no index for it:
-- `spare_requests` carried indexes on uid, stage, created_at and or_no, but not
-- on the column this join uses.
--
-- PLAIN, NOT PARTIAL, and that was a real mistake worth leaving written down.
-- The first attempt was `... (ucn) where coalesce(btrim(ucn), '') <> ''`, to
-- match the guard in the lateral below. But that guard is about the OUTER row
-- (`c.ucn`), not about `spare_requests` — so Postgres could not prove the
-- partial index applied to this scan and ignored it, leaving the lookup a
-- sequential scan per call. Measured: 1.2 ms per call across 920 calls, which
-- was more than half of what was left. A partial index is only usable when its
-- predicate follows from the query's own restriction on THAT table.
create index if not exists spare_requests_ucn_idx
  on public.spare_requests (ucn);

-- min(visit_at) per call, straight off the index rather than fetching every
-- visit row for the call and then discarding the ones with no date.
create index if not exists reports_ucn_visit_idx
  on public.reports (ucn, visit_at) where visit_at is not null;

create or replace view public.kpi_field_inst as
with c as (
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.field_calls where cancelled_at is null
  union all
  select ucn, call_number, reg_at, reg_date, complaint_date, party_name, city, state,
         product_name, serial, item_status, warranty_number, warranty_start, warranty_end,
         contract_number, contract_start, contract_end, contract_type, call_type,
         standard_complaint, complaint_reported, allocated_to, breakdown_date
    from public.installation_calls where cancelled_at is null
),
r as (
  select
    c.*,
    l.call_status, l.pending_reason, l.engineer,
    s.visit_at::date                              as solved_on,
    least(fv.at::date, fs.on_date)                as attended_on,
    -- The count runs from the LATER of complaint and registration: MIN of the
    -- two differences is the same thing said the workbook's way.
    greatest(c.complaint_date, coalesce(c.reg_at::date, c.reg_date))
                                                  as counts_from,
    coalesce(nullif(btrim(l.call_status), ''), 'Unattended') as status_now
    from c
    -- THE LATEST ENTRY, per call. Not the latest VISIT: a report written up
    -- late is still the latest thing the register was told (0032).
    left join lateral (
      select rl.call_status, rl.pending_reason, rl.engineer
        from public.reports rl
       where rl.ucn = c.ucn
       order by rl.updated_at desc, rl.id desc
       limit 1
    ) l on true
    left join lateral (
      select rs.visit_at
        from public.reports rs
       where rs.ucn = c.ucn
         and rs.call_status ilike 'solved%report%complet%'
       order by rs.updated_at desc, rs.id desc
       limit 1
    ) s on true
    left join lateral (
      select min(rf.visit_at) as at
        from public.reports rf
       where rf.ucn = c.ucn and rf.visit_at is not null
    ) fv on true
    -- An EMPTY ucn matches nothing, which the aggregate form got for free by
    -- excluding blank ucns before grouping. Correlated, the guard has to be
    -- said out loud or a call with no ucn would collect every ucn-less request.
    left join lateral (
      select min(coalesce(sq.or_req_date, sq.created_at::date)) as on_date
        from public.spare_requests sq
       where coalesce(btrim(c.ucn), '') <> ''
         and sq.ucn = c.ucn
    ) fs on true
)
select
  r.ucn                                          as "UC Number",
  r.call_number                                  as "Call Number",
  coalesce(r.reg_at, r.reg_date::timestamptz)    as "Call Registeration Date",
  r.complaint_date                               as "Complaint Date",
  r.party_name                                   as "Party Name",
  r.city                                         as "City",
  r.state                                        as "State",
  r.product_name                                 as "Product Name",
  r.serial                                       as "Product Serial Number",
  r.item_status                                  as "Item Status",
  r.warranty_number                              as "Warranty Number",
  r.warranty_start                               as "Warranty Start Date",
  r.warranty_end                                 as "Warranty End Date",
  r.contract_number                              as "Contract Number",
  r.contract_start                               as "Contract Start Date",
  r.contract_end                                 as "Contract End Date",
  r.contract_type                                as "Contract Type",
  r.call_type                                    as "Call Type",
  r.standard_complaint                           as "Standard Complaint",
  r.complaint_reported                           as "Complaint Reported",
  r.allocated_to                                 as "Call Allocated To",
  r.breakdown_date                               as "Breakdown Date",
  -- DECISION 3: any Solved... status is Close, report-pending included.
  case when r.status_now ilike 'solved%' then 'Close' else 'Open' end
                                                 as "Open/Close",
  r.status_now                                   as "Call Status",
  coalesce(r.pending_reason, '')                 as "CALL PENDING REASON",
  coalesce(r.engineer, '')                       as "Visiting Service Engineer",
  r.attended_on                                  as "Call Attended On",
  r.solved_on                                    as "Call Solved Date & Time",
  -- AC / AD. NULL when the thing being measured has not happened, rather than
  -- the sheet's 0 — see decision 1.
  --
  -- THE GUARD IS NOT DECORATION. `greatest()` IGNORES NULLs in Postgres, so
  -- `greatest(null - date, 0)` is 0, not null — and an unattended call would
  -- read "attended in 0 days, 00-03D", which is precisely the sheet behaviour
  -- this decision exists to undo. Caught by test 10, which was written for it.
  -- (It is the same property `least()` has, and there it is what we want: see
  -- Call Attended On in 0128.)
  case when r.attended_on is null or r.counts_from is null then null
       else greatest((r.attended_on - r.counts_from)::int, 0) end as "Attended in Days",
  case when r.solved_on is null or r.counts_from is null then null
       else greatest((r.solved_on - r.counts_from)::int, 0) end   as "Solved in Days",
  public.kpi_days_band(
    case when r.attended_on is null or r.counts_from is null then null
         else greatest((r.attended_on - r.counts_from)::int, 0) end)      as "TTA ( R )",
  public.kpi_days_band(
    case when r.solved_on is null or r.counts_from is null then null
         else greatest((r.solved_on - r.counts_from)::int, 0) end)        as "TTS ( R )",
  to_char(coalesce(r.reg_at, r.reg_date::timestamptz), 'YYYY Mon')        as "Failure Month",
  -- The column the workbook does not have. How long an OPEN call has been
  -- waiting, today — the question the sheet answered with a 0 that read as
  -- "attended and solved the same day".
  case when r.status_now ilike 'solved%' or r.counts_from is null then null
       else greatest(((now() at time zone 'Asia/Kolkata')::date - r.counts_from)::int, 0)
  end                                            as "Pending Days"
  from r;

-- RE-ASSERTED, because create-or-replace drops it. Without this the export
-- reads as the view's OWNER and every signed-in user gets every call —
-- silently, with no error. Three times in this project (0040, 0050, 0057).
alter view public.kpi_field_inst set (security_invoker = on);
grant select on public.kpi_field_inst to authenticated;

comment on view public.kpi_field_inst is
  'The KPI workbook''s Field_INST tab, columns A-AG. The per-call lookups into reports and spare_requests are LATERAL so the caller''s date range narrows the calls FIRST — pre-aggregating the whole of reports made a 455-call export scan 55,000 visits three times, which under RLS re-ran the call-visibility stack per row and timed out (0159).';

commit;
